head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFocusedCell]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Cell 에 포커스를 이동하고 편집 상태로 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 포커스가 이동할 Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "colInfo(필수) 파라미터로 포커스가 이동할 Cell 의 Column 인덱스 또는 ID 를 설정할 수 있어야 합니다.",
        "editMode(선택) 파라미터로 true 설정 시 Cell 이 포커스된 후 편집 상태로 설정되어야 합니다.",
        "editMode(선택) 파라미터로 false 또는 미설정 시 Cell 에 포커스만 이동하여야 합니다.",
        "setFocusedCell() 메소드 실행 시 기존의 포커스 및 편집 상태는 해제되어야 합니다.",
        "colInfo 파라미터에 숨겨진 Cell 을 설정 시 포커스는 되지만 화면에 표시되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (숨겨진 Column 포함)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" hidden="true" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_setFocusedCell_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = par_colInfo.getText();
    let editMode = par_editMode.getText();

    // colInfo 가 숫자인 경우 Number 로 변환
    if (!isNaN(colInfo) && colInfo !== '') {
        colInfo = Number(colInfo);
    }

    if (editMode === '') {
        target1.setFocusedCell(rowIndex, colInfo);
    } else {
        target1.setFocusedCell(rowIndex, colInfo, editMode === 'true');
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setFocusedCell(" + rowIndex + ", " + colInfo + ", " + editMode + ")");

    // 포커스 이동 여부 확인
    let focusedRowIndex = target1.getFocusedRowIndex();
    let focusedColIndex = target1.getFocusedColumnIndex();
    wf_body_bottom.getObj("scwin").setReturnValue("getFocusedRowIndex : " + focusedRowIndex + ", getFocusedColumnIndex : " + focusedColIndex);

    // 포커스된 셀의 편집 모드 여부 확인
    let isEdit = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("isEditing : " + isEdit);
}
